problems.starterCode:
export function countEventCodes(_codes: readonly string[]): Map<string, number> {
  return new Map<string, number>();
}

problems.solutionCode:
export function countEventCodes(codes: readonly string[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const code of codes) {
    const currentCount = counts.get(code);
    if (currentCount === undefined) counts.set(code, 1);
    else counts.set(code, currentCount + 1);
  }
  return counts;
}

problems.trapMutant:
