  const counts = new Map<string, number>();
  for (const code of codes) {
    const normalized = code.toLowerCase();
    counts.set(normalized, (counts.get(normalized) ?? 0) + 1);
  }
  return counts;
}

problems.starterCode:
type LedgerEntry = { accountId: number; amountCents: number };

export function groupLedgerEntries(_entries: readonly LedgerEntry[]): Map<number, LedgerEntry[]> {
  return new Map<number, LedgerEntry[]>();
}

problems.solutionCode:
type LedgerEntry = { accountId: number; amountCents: number };

export function groupLedgerEntries(entries: readonly LedgerEntry[]): Map<number, LedgerEntry[]> {
  const groups = new Map<number, LedgerEntry[]>();
  for (const entry of entries) {
    const group = groups.get(entry.accountId);
    if (group === undefined) {
      groups.set(entry.accountId, [entry]);
    } else {
      group.push(entry);
    }
  }
  return groups;
}

