problems.starterCode:
export function uniquePackageAliases(aliases: readonly string[]): string[] {
  return [...new Set(aliases)].sort();
}

problems.solutionCode:
export function uniquePackageAliases(aliases: readonly string[]): string[] {
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const alias of aliases) {
    if (seen.has(alias)) continue;
    seen.add(alias);
    unique.push(alias);
  }
  return unique;
}

