type OwnerSession = { id: string };
type ScheduledTicket = { owner: OwnerSession; ticketCode: string };

export function groupTicketsByOwner(tickets: readonly ScheduledTicket[]): Map<OwnerSession, string[]> {
  const groups = new Map<OwnerSession, string[]>();
  for (const ticket of tickets) {
    const group = groups.get(ticket.owner);
    if (group === undefined) {
      groups.set(ticket.owner, [ticket.ticketCode]);
    } else {
      group.push(ticket.ticketCode);
    }
  }
  return groups;
}

